// Structure AoS : intuitive, mais moins coalescée qu'une représentation SoA.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Deux cibles par thread ; les champs de chaque source sont réutilisés en registres.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i0 = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    int i1 = i0 + blockDim.x;
    bool active0 = i0 < n;
    bool active1 = i1 < n;
    if (!active0 && !active1) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    Particle p0;
    Particle p1;
    if (active0) p0 = in[i0];
    if (active1) p1 = in[i1];

    float fx0 = 0.0f, fy0 = 0.0f, fz0 = 0.0f;
    float fx1 = 0.0f, fy1 = 0.0f, fz1 = 0.0f;

    for (int j = 0; j < n; j++) {
        const float sx = in[j].x;
        const float sy = in[j].y;
        const float sz = in[j].z;
        const float sm = in[j].mass;

        if (active0 && i0 != j) {
            float dx = sx - p0.x;
            float dy = sy - p0.y;
            float dz = sz - p0.z;

            float distSq = dx * dx + dy * dy + dz * dz + softening;
            float dist = sqrtf(distSq);
            float f = (G * p0.mass * sm) / (distSq * dist);

            fx0 += f * dx;
            fy0 += f * dy;
            fz0 += f * dz;
        }

        if (active1 && i1 != j) {
            float dx = sx - p1.x;
            float dy = sy - p1.y;
            float dz = sz - p1.z;

            float distSq = dx * dx + dy * dy + dz * dz + softening;
            float dist = sqrtf(distSq);
            float f = (G * p1.mass * sm) / (distSq * dist);

            fx1 += f * dx;
            fy1 += f * dy;
            fz1 += f * dz;
        }
    }

    if (active0) {
        p0.vx += (fx0 / p0.mass) * dt;
        p0.vy += (fy0 / p0.mass) * dt;
        p0.vz += (fz0 / p0.mass) * dt;

        p0.x += p0.vx * dt;
        p0.y += p0.vy * dt;
        p0.z += p0.vz * dt;

        out[i0] = p0;
    }

    if (active1) {
        p1.vx += (fx1 / p1.mass) * dt;
        p1.vy += (fy1 / p1.mass) * dt;
        p1.vz += (fz1 / p1.mass) * dt;

        p1.x += p1.vx * dt;
        p1.y += p1.vy * dt;
        p1.z += p1.vz * dt;

        out[i1] = p1;
    }
}
